import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// spec: specs/hal-engine-config-hooks/spec.md#8
it('preserves a thrown string as the onError cause and caller rejection', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const errors: Error[] = [];
  const orchestrator = createChatOrchestrator(createMockProvider(), new PromptBuilder({identity: 'Test assistant'}), undefined, {
    hooks: {
      beforeSession: async () => {
        throw 'string boom';
      },
      onError: async (_session, error) => {
        errors.push(error);
      },
    },
  });

  const outcome = await orchestrator.processMessage(session).then(
    () => ({rejected: false, reason: undefined as unknown}),
    (reason: unknown) => ({rejected: true, reason})
  );

  expect({outcome, errors, cause: errors[0]?.cause}).toEqual({
    outcome: {rejected: true, reason: 'string boom'},
    errors: [new Error('string boom')],
    cause: 'string boom',
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
